echo "== plans 2026 by strategy =="; python3 - <<'EOF'
import json,glob,collections,os
fs=sorted(glob.glob('data/trade_plans/*2026*.json'))
c=collections.Counter(); ex={}
for f in fs:
    try: d=json.load(open(f))
    except Exception as e: c['<unreadable>']+=1; continue
    s=d.get('strategy') if isinstance(d,dict) else None
    c[str(s)]+=1; ex.setdefault(str(s),os.path.basename(f))
print(len(fs), dict(c)); print(ex)
EOF
echo "== plan_[REDACTED]_[REDACTED] =="; ls -la data/trade_plans/plan_[REDACTED]_[REDACTED].json 2>/dev/null; python3 -c "
import json;d=json.load(open('data/trade_plans/plan_[REDACTED]_[REDACTED].json'))
print({k:d[k] for k in d if k not in ('orders','notes','positions','holds')})
nb=d.get('nav_basis') or d.get('nav') or {}
print('nav_basis',nb)
import re; s=json.dumps(d); print([m for m in re.findall(r'\"[a-z_]*nav[a-z_]*\": ?[0-9.]+', s)][:20])
"
echo "== get_nav callers =="; grep -rnE "\.get_nav\s*\(" --include=*.py . | grep -v "/\.git/" | head -30
echo "== A/B script =="; grep -rlE "cq20260913|ab_nav|nav_include_egg_offbook" --include=*.py --include=*.sh --include=*.md . 2>/dev/null | grep -v "/\.git/" | head -20

